import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as r,o as e,c as d,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"swag2mcp","description":"","frontmatter":{},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md","lastUpdated":1784903584000}'),o={name:"ru/index.md"};function n(i,t,p,c,l,h){return e(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="swag2mcp" tabindex="-1">swag2mcp <a class="header-anchor" href="#swag2mcp" aria-label="Permalink to &quot;swag2mcp&quot;">​</a></h1><div style="background:#dc2626;color:white;padding:20px 24px;border-radius:12px;text-align:center;font-size:1.4em;font-weight:700;margin:24px 0;"> 🚧 WORK IN PROGRESS — релиз скоро! </div><p>Объединяет спецификации OpenAPI/Swagger/Postman с LLM-агентами через протокол MCP.</p><a href="https://www.youtube.com/watch?v=1Da4UmE2f9U" target="_blank"><img src="https://raw.githubusercontent.com/mmadfox/swag2mcp/main/docs/cover.png" alt="Превью"></a><h2 id="ваше-api-говорит-на-языке-llm" tabindex="-1">Ваше API говорит на языке LLM <a class="header-anchor" href="#ваше-api-говорит-на-языке-llm" aria-label="Permalink to &quot;Ваше API говорит на языке LLM&quot;">​</a></h2><p>Одна строка конфига превращает любой файл OpenAPI/Swagger/Postman в MCP-сервер. LLM-агенты обнаруживают, изучают и вызывают ваши API — без единой строки интеграционного кода.</p><img src="'+a+'" width="700" alt="Архитектура swag2mcp"><h2 id="хватит-писать-обертки" tabindex="-1">Хватит писать обёртки <a class="header-anchor" href="#хватит-писать-обертки" aria-label="Permalink to &quot;Хватит писать обёртки&quot;">​</a></h2><p>Каждый раз, подключая новый API к LLM, вы пишете один и тот же шаблонный код: разбор спецификаций, аутентификация, обработка ошибок, ограничение запросов. swag2mcp делает это за вас — 19 готовых MCP-инструментов.</p><h2 id="кому-это-нужно" tabindex="-1">Кому это нужно <a class="header-anchor" href="#кому-это-нужно" aria-label="Permalink to &quot;Кому это нужно&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Роль</th><th>Зачем</th></tr></thead><tbody><tr><td><strong>Разработчик AI-агентов</strong></td><td>Подключить любой API за 2 минуты, а не за 2 дня</td></tr><tr><td><strong>MCP-инженер</strong></td><td>Ни строчки кода обработчика — просто укажите спецификацию</td></tr><tr><td><strong>Архитектор</strong></td><td>Единый слой интеграции API для всех LLM в компании</td></tr><tr><td><strong>Аналитик данных</strong></td><td>Доступ к API через естественный язык, без программирования</td></tr><tr><td><strong>DevOps / SRE</strong></td><td>Мониторинг и автоматизация через LLM без дополнительных сервисов</td></tr><tr><td><strong>Интегратор</strong></td><td>9 методов аутентификации из коробки — от Basic до OAuth2 и HMAC</td></tr><tr><td><strong>QA-инженер</strong></td><td>Mock-сервер для изолированного тестирования без реальных API</td></tr><tr><td><strong>Продукт-менеджер</strong></td><td>Быстрые прототипы AI-функций без бэкенд-работы</td></tr><tr><td><strong>и многие другие</strong></td><td></td></tr></tbody></table><hr><h2 id="лицензия" tabindex="-1">Лицензия <a class="header-anchor" href="#лицензия" aria-label="Permalink to &quot;Лицензия&quot;">​</a></h2><p>Распространяется под лицензией <strong>GNU Affero General Public License v3.0</strong> (AGPL v3).</p><p>Полный текст лицензии: <a href="https://github.com/mmadfox/swag2mcp/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPDX-License-Identifier: AGPL-3.0-only</span></span></code></pre></div>',16)])])}const b=r(o,[["render",n]]);export{u as __pageData,b as default};
